// Validate approval input + assemble the 19-section package. Missing sections stay 'unavailable', never fabricated.
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
if (!i.snapshot && !i.procurement) throw new Error('Missing procurement snapshot');
const S = (v, dflt) => (v === undefined || v === null ? 'unavailable' : v);
const pkg = {
  procurement_id: i.procurement_id,
  procurement_request: i.snapshot?.procurement ?? i.procurement ?? 'unavailable',
  selected_product: i.selected_product ?? 'unavailable',
  selected_vendor: i.selected_vendor ?? 'unavailable',
  original_offer: i.original_offer ?? 'unavailable',
  revised_offer: i.revised_offer ?? 'unavailable',
  original_score: i.original_score ?? 'unavailable',
  revised_score: i.revised_score ?? 'unavailable',
  savings: i.savings ?? 'unavailable',
  quality_evidence: i.quality_evidence ?? 'unavailable',
  review_evidence: i.review_evidence ?? 'unavailable',
  delivery_information: i.delivery_information ?? 'unavailable',
  warranty_information: i.warranty_information ?? 'unavailable',
  payment_terms: i.payment_terms ?? 'unavailable',
  criteria_used: i.criteria_used ?? [],
  criteria_missing: i.criteria_missing ?? [],
  limitations: i.limitations ?? ['No verified commercial data available'],
  evidence_urls: i.evidence_urls ?? [],
  negotiation_history: i.negotiation_history ?? [],
  status: 'PENDING_APPROVAL', approved_by: null, approved_at: null, decision_reason: null,
  expires_at: i.expires_at ?? null,
};
const missing = ['procurement_request'].filter((s) => pkg[s] === undefined);
if (missing.length) throw new Error('package missing sections: ' + missing.join(','));
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, package: pkg, expires_at: pkg.expires_at } }];

// Validate the HUMAN decision strictly. Only APPROVED/REJECTED/CHANGES_REQUESTED with explicit non-placeholder actor.
const pkg = $('Build Package').first().json.package;
const w = $input.first().json?.body ?? $input.first().json;
const bad = [];
if (!['APPROVED','REJECTED','CHANGES_REQUESTED'].includes(w.decision)) bad.push('invalid decision (absence/timeout/views are never approval): ' + w.decision);
const actor = typeof w.actor === 'string' ? w.actor.trim() : '';
if (actor.length < 2 || ['unknown','n/a','tbd','test','todo','none'].includes(actor.toLowerCase())) bad.push('placeholder actor identity');
if (!w.decided_at) bad.push('decision timestamp missing');
if (w.procurement_id && w.procurement_id !== pkg.procurement_id) bad.push('procurement mismatch');
if (bad.length) throw new Error('human decision rejected: ' + bad.join('; '));
return [{ json: { procurement_id: pkg.procurement_id, trace_id: $('Build Package').first().json.trace_id, outcome: w.decision, approved_by: actor, approved_at: w.decided_at, decision_reason: typeof w.reason === 'string' ? w.reason : null, package: { ...pkg, status: w.decision === 'APPROVED' ? 'APPROVED' : w.decision === 'REJECTED' ? 'REJECTED' : 'CHANGES_REQUESTED', approved_by: actor, approved_at: w.decided_at } } }];
